import { accessibilityTree, accessibilityNode, moveKeyboardTo } from './accessibility-tree.ts';
import { accessibilityFixture, playwrightVersion } from './accessibility-fixture.ts';
import { loadTimedBoard } from './game-fixture.ts';

test('a complete keyboard journey exposes names, states and each result in Chromium accessibility trees', async ({
  page,
  context,
  browser,
}, artifacts) => {
  const expected = await accessibilityFixture();
  await loadTimedBoard(page);
  const session = await context.newCDPSession(page);
  await session.send('Accessibility.enable');
  const captures: { stage: string; tree: Awaited<ReturnType<typeof accessibilityTree>> }[] = [];
  async function capture(stage: string) {
    const tree = await accessibilityTree(session);
    captures.push({ stage, tree });
    return tree;
  }
  await page.getByRole('combobox', { name: expected.controls.size, exact: true }).focus();
  const controls = await capture('controls');
  expect(accessibilityNode(controls, 'combobox', expected.controls.size).properties.focused).toBe(
    true,
  );
  accessibilityNode(controls, 'button', expected.controls.newGame);
  await page.keyboard.press('Tab');
  expect(
    accessibilityNode(await capture('new-game-control'), 'button', expected.controls.newGame)
      .properties.focused,
  ).toBe(true);
  await page.keyboard.press('Tab');
  await page.keyboard.press('Tab');
  const closed = await capture('board-entry');
  for (const name of expected.closed) accessibilityNode(closed, 'button', name);
  expect(accessibilityNode(closed, 'button', expected.closed[0]).properties.focused).toBe(true);
  await page.getByRole('status').evaluate((element) => {
    const results: string[] = [];
    element.setAttribute('data-result-history', '[]');
    new MutationObserver(() => {
      results.push(element.textContent ?? '');
      element.setAttribute('data-result-history', JSON.stringify(results));
    }).observe(element, { childList: true, subtree: true, characterData: true });
  });
  for (const [turn, pair] of EXAMPLE_PAIRS.entries()) {
    await moveKeyboardTo(page, pair[0], expected.size);
    await page.keyboard.press('Enter');
    const revealed = await capture(`revealed-${turn + 1}`);
    expect(
      accessibilityNode(revealed, 'button', expected.revealed[pair[0]]).properties.focused,
    ).toBe(true);
    if (turn === 0) await page.clock.runFor(3000);
    await moveKeyboardTo(page, pair[1], expected.size);
    await page.keyboard.press('Space');
    const matched = await capture(`turn-${turn + 1}`);
    for (const index of pair)
      expect(
        accessibilityNode(matched, 'button', expected.matched[index]).properties.disabled,
      ).toBe(true);
    const result = accessibilityNode(matched, 'status');
    expect(result.properties.live).toBe('polite');
    expect(result.properties.atomic).toBe(true);
    expect(result.text).toBe(expected.turns[turn]);
  }
  const win = await capture('completed');
  expect(win.filter((node) => node.role === 'paragraph').map((node) => node.text)).toContain(
    expected.win,
  );
  const announcements: unknown = JSON.parse(
    (await page.getByRole('status').getAttribute('data-result-history')) ?? '[]',
  );
  expect(announcements).toEqual(expected.turns);
  await page.keyboard.press('Tab');
  expect(await page.locator('.card:focus').count()).toBe(0);
  const exit = await capture('board-exit');
  expect(
    accessibilityNode(exit, 'DisclosureTriangle', expected.controls.summary).properties.focused,
  ).toBe(true);
  await page.keyboard.press('Shift+Tab');
  await page.keyboard.press('Shift+Tab');
  await page.keyboard.press('Shift+Tab');
  await page.keyboard.press('Enter');
  const reset = await capture('new-game');
  expect(accessibilityNode(reset, 'button', expected.controls.newGame).properties.focused).toBe(
    true,
  );
  for (const name of expected.closed) accessibilityNode(reset, 'button', name);
  expect(accessibilityNode(reset, 'status').text).toBe(expected.newGame);
  await page.locator('summary').click();
  await page.getByRole('button', { name: 'Export snapshot', exact: true }).click();
  const snapshot = await page.getByLabel('Snapshot JSON', { exact: true }).inputValue();
  const loadEvents = [
    {
      stage: 'invalid-board',
      field: 'Board code',
      value: 'invalid',
      button: 'Load board',
      notice: 'Invalid board code.',
    },
    {
      stage: 'invalid-snapshot',
      field: 'Snapshot JSON',
      value: '{',
      button: 'Load snapshot',
      notice: 'Invalid snapshot.',
    },
    {
      stage: 'loaded-snapshot',
      field: 'Snapshot JSON',
      value: snapshot,
      button: 'Load snapshot',
      notice: 'Loaded snapshot. Select Resume to continue.',
    },
  ];
  for (const event of loadEvents) {
    await page.getByLabel(event.field, { exact: true }).fill(event.value);
    const button = page.getByRole('button', { name: event.button, exact: true });
    for (let repeat = 1; repeat <= 2; repeat += 1) {
      await button.click();
      await expect(button).toBeFocused();
      await expect(page.locator('.load-notice')).toHaveText(event.notice);
      const tree = await capture(`${event.stage}-${repeat}`);
      const status = accessibilityNode(tree, 'status');
      expect(tree.filter((node) => node.role === 'status')).toHaveLength(1);
      expect(status.properties.live).toBe('polite');
      expect(status.properties.atomic).toBe(true);
      expect(status.text).toBe(event.notice);
    }
  }
  await expect(page.getByRole('button', { name: 'Resume', exact: true })).toBeVisible();
  // A paused import blocks activation without marking its unmatched cards disabled.
  await expect(page.locator('.card[aria-disabled="true"]')).toHaveCount(0);
  expect(
    JSON.parse((await page.getByRole('status').getAttribute('data-result-history')) ?? '[]'),
  ).toEqual([
    ...expected.turns,
    expected.newGame,
    ...loadEvents.flatMap((event) => [event.notice, event.notice]),
  ]);
  const readme = await readFile(new URL('../README.md', import.meta.url), 'utf8');
  expect(readme.split(/\r?\n/)).toContain(expected.readmeRecord);
  const record =
    JSON.stringify(
      {
        schemaVersion: 1,
        status: 'tree-checked',
        chromium: browser.version(),
        playwright: await playwrightVersion(),
        screenReader: null,
        spokenReview: 'User acceptance. No spoken output was tested by the developer.',
        captures,
      },
      null,
      2,
    ) + '\n';
  expect(record).not.toMatch(
    /\b(?:file|https?):\/\/|[A-Za-z]:[\\/]|nodeId|frameId|backendDOMNodeId/,
  );
  await writeFile(artifacts.outputPath('accessibility-journey.json'), record);
  await session.detach();
}, {}, Scrollbars.hidden, TestTimeouts.long);
import { expect, test } from './browser-test.ts';
import { EXAMPLE_CODE } from '../src/game/game.fixture.ts';
import { DealControl, ReproductionControl } from '../src/game/controls/control-labels.ts';
import { SNAPSHOT_VERSION } from '../src/game/snapshot.ts';
import { SelectionKind } from '../src/game/selection.ts';
import { boardCode, parseBoardCode } from '../src/game/deck.ts';
import { loadFixedBoard, PHONE } from './game-fixture.ts';
import { boardGaps } from './focus-bounds.ts';
import { moveKeyboardTo } from './accessibility-tree.ts';
import type { Page } from '@playwright/test';

const SIZE = 16;
// Row 7, column 11 sits past the right edge of a phone board scrolled back to its start.
const REMEMBERED = 6 * SIZE + 10;
// Row 15, column 16 sits past the right and bottom edges of that board.
const FAR = 14 * SIZE + 15;
const EXAMPLE_SIZE = parseBoardCode(EXAMPLE_CODE)?.size ?? 0;

async function scrollBoardToStart(page: Page): Promise<void> {
  await page.locator('.board-viewport').evaluate((viewport) => viewport.scrollTo(0, 0));
  await page.evaluate(() => new Promise((ready) => requestAnimationFrame(ready)));
}

test('Tab and Shift+Tab bring the remembered card in with nearest alignment', async ({ page }) => {
  await page.setViewportSize(PHONE);
  await loadFixedBoard(page);
  await page.getByLabel(DealControl.size, { exact: true }).selectOption(String(SIZE));
  const restart = page.getByRole('button', { name: DealControl.restart, exact: true });
  await restart.focus();
  await page.keyboard.press('Tab');
  await moveKeyboardTo(page, REMEMBERED, SIZE);
  const card = page.locator('.card').nth(REMEMBERED);
  for (const enter of ['Shift+Tab', 'Tab']) {
    if (enter === 'Shift+Tab') await page.keyboard.press('Tab');
    else await restart.focus();
    await scrollBoardToStart(page);
    await page.keyboard.press(enter);
    await expect(card).toBeFocused();
    const gaps = await boardGaps(card);
    expect(gaps.right, `I13 ${enter} enters with nearest alignment`).toBeCloseTo(gaps.margin, 0);
  }
});

test('Resume returns focus to the remembered card with nearest alignment', async ({ page }) => {
  await page.setViewportSize(PHONE);
  await loadFixedBoard(page);
  await page.locator('summary').click();
  const paused = {
    version: SNAPSHOT_VERSION,
    boardCode: boardCode(SIZE, 1),
    matched: [],
    selection: { kind: SelectionKind.one, index: 0 },
    moves: 0,
    elapsedMs: 0,
    started: true,
  };
  await page.getByLabel(ReproductionControl.snapshot, { exact: true }).fill(JSON.stringify(paused));
  await page.getByRole('button', { name: ReproductionControl.loadSnapshot, exact: true }).click();
  await page.locator('.card').first().focus();
  await moveKeyboardTo(page, FAR, SIZE);
  const card = page.locator('.card').nth(FAR);
  await expect(card).toBeFocused();
  await scrollBoardToStart(page);
  await page.getByRole('button', { name: ReproductionControl.resume, exact: true }).click();
  await expect(card).toBeFocused();
  const gaps = await boardGaps(card);
  expect(gaps.right, 'I13 Resume returns with nearest alignment').toBeCloseTo(gaps.margin, 0);
  expect(gaps.bottom, 'I13 Resume returns with nearest alignment').toBeCloseTo(gaps.margin, 0);
});

test('every keyboard move after a pointer click shows the focus outline', async ({ page }) => {
  await loadFixedBoard(page);
  const cards = page.locator('.card');
  await cards.nth(5).click();
  for (const [key, index] of [
    ['ArrowRight', 6],
    ['ArrowDown', 6 + EXAMPLE_SIZE],
    ['ArrowLeft', 5 + EXAMPLE_SIZE],
    ['ArrowUp', 5],
  ] as const) {
    await page.keyboard.press(key);
    await expect(cards.nth(index)).toBeFocused();
    await expect(cards.nth(index), `V16 outline after ${key}`).toHaveCSS('outline-style', 'solid');
    await expect(cards.nth(index), `V16 outline after ${key}`).toHaveCSS('outline-width', '3px');
  }
});
import { expect, test } from './browser-test.ts';
import { EXAMPLE_CODE } from '../src/game/game.fixture.ts';
import { DealControl, ReproductionControl } from '../src/game/controls/control-labels.ts';
import { GRID_SIZES } from '../src/game/deck.ts';
import { SessionNotice } from '../src/game/session/session.ts';
import { loadTimedBoard, exportedSnapshot, GAME_URL } from './game-fixture.ts';

// The published input limits, kept apart from the components that set them.
const BOARD_CODE_MAX_CHARACTERS = 32;
const SNAPSHOT_MAX_CHARACTERS = 65_536;

test('native reproduction controls keep drafts, limits, exact errors and action focus', async ({
  page,
}) => {
  await page.goto(GAME_URL);
  await expect(page.locator('details')).not.toHaveAttribute('open');
  await expect(page.locator('summary')).toHaveText(ReproductionControl.summary);
  const options = await page
    .getByLabel(DealControl.size, { exact: true })
    .locator('option')
    .evaluateAll((items) =>
      items.map((item) => {
        if (!(item instanceof HTMLOptionElement)) throw new Error('Expected a native option.');
        return { value: item.value, text: item.textContent };
      }),
    );
  expect(options).toEqual(
    GRID_SIZES.map((size) => ({ value: String(size), text: `${size}x${size}` })),
  );
  await loadTimedBoard(page);
  await page.locator('summary').click();
  const code = page.getByLabel(ReproductionControl.board, { exact: true });
  const field = page.getByLabel(ReproductionControl.snapshot, { exact: true });
  await expect(code).toHaveAttribute('maxlength', String(BOARD_CODE_MAX_CHARACTERS));
  await expect(field).toHaveAttribute('maxlength', String(SNAPSHOT_MAX_CHARACTERS));
  await code.fill('draft');
  await page.locator('.card').first().click();
  expect(await code.inputValue()).toBe('draft');
  const load = page.getByRole('button', { name: ReproductionControl.loadBoard, exact: true });
  await load.click();
  await expect(load).toBeFocused();
  await expect(page.locator('.load-notice')).toHaveText(SessionNotice.invalidBoard);
  await field.fill('{');
  const importButton = page.getByRole('button', {
    name: ReproductionControl.loadSnapshot,
    exact: true,
  });
  await importButton.click();
  await expect(importButton).toBeFocused();
  await expect(page.locator('.load-notice')).toHaveText(SessionNotice.invalidSnapshot);
  const exportButton = page.getByRole('button', {
    name: ReproductionControl.exportSnapshot,
    exact: true,
  });
  await exportButton.click();
  await expect(exportButton).toBeFocused();
  const text = await field.inputValue();
  expect(text).toContain('\n');
  await field.selectText();
  expect(
    await field.evaluate((element) => {
      if (!(element instanceof HTMLTextAreaElement)) throw new Error('Expected a textarea.');
      return element.selectionEnd - element.selectionStart;
    }),
  ).toBe(text.length);
  await code.fill(EXAMPLE_CODE);
  await load.click();
  await expect(load).toBeFocused();
  await page.locator('summary').click();
  expect(await exportedSnapshot(page)).toMatchObject({ moves: 0, elapsedMs: 0, started: false });
});
import { expect, test } from './browser-test.ts';
import { DealControl } from '../src/game/controls/control-labels.ts';
